head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.seq = "";
scwin.gRow = 1;
// 화면 리사이징

scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.Combo_CBDataSetPeriodYear(cmb_PeriodTp);
        await scwin.setCode();
        cmb_MotivTp.setValue("");
        cmb_SignifTp.setValue("");
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.seq = dts_List.getCellData(row, "SEQ");
        scwin.gRow = row;
        scwin.setContnId(row);
        if (scwin.seq !== "") {
            if (colid === "COMITE_DD") {
                const options = {
                    id: "ULDSTF35151",
                    title: "불성실공시 심의 관리(코) 수정",
                    type: "browserPopup",
                    width: "630px",
                    height: "750px",
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("/dsclmgt/ULDSTF35151.gfm", options);
            } else if (colid === "COM_ABBRV") {
                $c.stf.fn_PopupCorpInfo();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Insert_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Insert_onclick = async function() {
    try {
        scwin.seq = "";
        const options = {
            id: "ULDSTF35151",
            title: "불성실공시 심의 관리(코) 등록",
            type: "browserPopup",
            width: "630px",
            height: "750px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF35151.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.btn_Insert_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF35150.xml', SCREN_PROCS_TP_CD_07);
        const file_name = "불성실공시 심의관리 목록";
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
        $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_NfaithTp_OnLoadError
 * @description dts_NfaithTp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_NfaithTp_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_NfaithTp);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.dts_NfaithTp_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총건수 : " + rowcount);
        }
        dts_List.setRowPosition(scwin.gRow, 0);
        scwin.gRow = 1;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35150.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        scwin.setFromToDateYear(edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35150.img_com_srch_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    cmb_PeriodTp.setValue(vCurDate.substring(0, 4));
    scwin.setFromToDateYear(edt_FromDate, edt_ToDate);

    // 위반중요성유형  셋팅
    // dts_SignifTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT"+
    //                        "&FOR=C&CD_ENG_NM=DISCLS_VIOL_SIGNIF_TP_CD";
    // dts_SignifTp.Reset();

    // 위반동기유형  셋팅
    // dts_MotivTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT"+
    //                        "&FOR=C&CD_ENG_NM=DISCLS_VIOL_MOTIV_TP_CD";
    // dts_MotivTp.Reset();

    // 불성실유형  셋팅
    const sbmOptions = {
        id : "sbm_dts_NfaithTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_NfaithTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    txb_TotalCnt.setValue("총건수 : ");

    // 그리드의 데이타 조회
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/UnfaithfulDesign.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkCond
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("위원회 일시를 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("위원회 일시를 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    await scwin.search();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name Combo_CBDataSetPeriodYear
 * @description Combo CBData Set Period Year 처리
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.Combo_CBDataSetPeriodYear = function(sval) {
    const date = new Date();
    let yy = date.getFullYear();
    let usrCBData = "";
    while (yy >= 2000) {
        if (yy !== date.getFullYear()) usrCBData += ",";
        usrCBData += yy + "년도^" + yy;
        yy--;
    }
    sval.CBData = usrCBData;
};

/**
 * @method
 * @name setFromToDateYear
 * @description set From To Date Year 처리
 * @param {*} pObjFrom pObjFrom
 * @param {*} pObjTo pObjTo
 * @returns {void}
 * @hidden N
 */
scwin.setFromToDateYear = function(pObjFrom, pObjTo) {
    let yy = cmb_PeriodTp.getValue();
    // var today = cGetToday("yyyymmdd");
    const vFrom = yy + "0101";
    const vTo = yy + "1231";
    pObjFrom.setValue(vFrom);
    // setObjectValue(pObjTo,  today>vTo?vTo:today);
    pObjTo.setValue(vTo);
};
